    seen=np.zeros((H,W),bool); comps=[]
    for i in range(H):
        for j in range(W):
            if a[i,j]!=bg and not seen[i,j]:
                col=int(a[i,j]); q=[(i,j)]; seen[i,j]=True; cells=[(i,j)]
                while q:
                    r,c=q.pop()
                    for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                        rr,cc=r+dr,c+dc
                        if 0<=rr<H and 0<=cc<W and not seen[rr,cc] and int(a[rr,cc])==col:
                            seen[rr,cc]=True;q.append((rr,cc));cells.append((rr,cc))
                comps.append((col,cells))
    out=a.copy()
    kept=set()
    for c,cells in comps:
        if len(cells)>=4: kept|=set(cells)
    for i in range(H):
        for j in range(W):
            if a[i,j]!=bg and (i,j) not in kept:
                nb=[a[r][c] for r in [i-1,i,i+1] for c in [j-1,j,j+1] if 0<=r<H and 0<=c<W and (r,c)!=(i,j)]
                vals=[int(n) for n in nb if int(n)!=bg]
                mv=major=Counter(vals).most_common(1)[0][0] if vals else bg
                out[i][j]=major
    return out.tolist()
